import {features, coin, phases} from './data.js';
import {stations,categories,stationPhotos} from './gallery-data.js';
import {renderChapters} from './lateral-chapters.js';
const worlds=stations;
const allFeatures=[...features,coin], $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fa=n=>new Intl.NumberFormat('fa-IR').format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=0, progress=0, reduced=matchMedia('(prefers-reduced-motion: reduce)').matches, scene=null;
document.body.classList.toggle('reduced-motion',reduced);
$('#motion-toggle').setAttribute('aria-pressed',String(reduced));
$('#journey').innerHTML=renderChapters(stations,allFeatures);
const chapters=$$('.chapter');
$('.chapter-rail').innerHTML=worlds.map((w,i)=>`<button class="rail-item ${i===0?'active':''}" data-chapter="${i}" aria-label="رفتن به ${w.name}" ${i===0?'aria-current="step"':''}><span class="rail-dot"></span><span class="rail-label">${w.name}</span></button>`).join('');
$('.atlas-grid').innerHTML=worlds.map((w,i)=>`<button class="atlas-card" data-chapter="${i}"><img src="assets/${w.photo}" alt="" loading="lazy"><span>${w.num}</span><b>${w.name}</b><small>${w.en}</small></button>`).join('');
$('#world-filter').insertAdjacentHTML('beforeend',categories.slice(1).map((w,i)=>`<option value="${i+1}">${w.name}</option>`).join(''));
const dialogs=$$('dialog');
function openDialog(id){const d=$('#'+id);if(!d.open)d.showModal();document.body.classList.add('modal-open');}
function closeDialog(d){d.close();if(!dialogs.some(v=>v.open))document.body.classList.remove('modal-open');}
dialogs.forEach(d=>{d.querySelector('.close').onclick=()=>closeDialog(d);d.addEventListener('close',()=>{if(!dialogs.some(v=>v.open))document.body.classList.remove('modal-open')});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function goTo(i){dialogs.forEach(d=>{if(d.open)closeDialog(d)});$('#'+worlds[i].id).scrollIntoView({behavior:reduced?'instant':'smooth'});}
function showFeature(id){const f=allFeatures.find(f=>f.id===id);if(!f)return;$('#detail-category').textContent=f.tag;$('#detail-content').innerHTML=`<span class="detail-phase">قابلیت پیشنهادی · فاز ${fa(f.phase)} / ${phases[f.phase].title}</span><figure class="detail-photo"><img src="assets/${stationPhotos[f.id][0]}" alt="${f.title}"><figcaption>${stationPhotos[f.id][1]}</figcaption></figure><h2>${f.title}</h2><p class="detail-lead">${f.intro}</p><p>${f.body}</p><h3>تجربه چگونه کار می‌کند؟</h3><ol class="detail-steps">${f.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="detail-example"><h3>یک سناریوی ملموس</h3><p>${f.example}</p></div><h3>پیش‌نیاز اجرا</h3><p>${f.needs}</p><p class="small-note">بر اساس پیشنهادنامه شهر هوشمند شاهرود. زمان‌بندی هر قابلیت پس از شناخت سامانه‌های موجود و امکان‌سنجی نهایی می‌شود.</p>`;openDialog('detail');$('#detail').scrollTop=0;}
document.addEventListener('click',e=>{const f=e.target.closest('[data-feature]');if(f)showFeature(f.dataset.feature);const c=e.target.closest('[data-chapter]');if(c)goTo(Number(c.dataset.chapter));if(e.target.closest('[data-library]'))showLibrary();});
function normalize(s){return s.replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/\u200c/g,' ').toLowerCase();}
function renderLibrary(){const term=normalize($('#feature-search').value.trim()),filter=$('#world-filter').value;const result=allFeatures.filter(f=>(filter==='all'||f.world===Number(filter))&&normalize(f.title+' '+f.tag+' '+f.body).includes(term));$('#result-count').textContent=fa(result.length)+' امکان برای کاوش';$('.feature-list').innerHTML=result.length?result.map(f=>`<button class="library-item" data-feature="${f.id}"><span class="item-no">${f.n}</span><span><b>${f.title}</b><small>${categories[f.world].name} · فاز ${fa(f.phase)}</small></span><span class="arrow">↗</span></button>`).join(''):'<p class="empty-state">موردی پیدا نشد. عبارت دیگری بنویسید یا فیلتر دنیا را تغییر دهید.</p>';}
function showLibrary(){renderLibrary();openDialog('library');}
$('#open-library').onclick=showLibrary;$('#closing-library').onclick=showLibrary;$('#open-atlas').onclick=()=>openDialog('atlas');$('#open-credits').onclick=()=>openDialog('credits');$('#feature-search').addEventListener('input',renderLibrary);$('#world-filter').addEventListener('change',renderLibrary);
$('.phase-track').innerHTML=phases.map((p,i)=>`<button class="phase-tab" id="phase-tab-${i}" role="tab" aria-selected="${i===0}" aria-controls="phase-detail" tabindex="${i===0?0:-1}" data-phase="${i}"><span class="phase-number">${p.n}</span><b>${p.title}</b><small>${p.time}</small></button>`).join('');
function selectPhase(i,focus=false){$$('.phase-tab').forEach((t,j)=>{t.setAttribute('aria-selected',String(i===j));t.tabIndex=i===j?0:-1;if(focus&&i===j)t.focus()});const p=phases[i];$('#phase-detail').innerHTML=`<p>${p.desc}</p><span>${p.deliver}</span>`;$('#phase-detail').setAttribute('aria-labelledby','phase-tab-'+i);}
$$('.phase-tab').forEach((t,i)=>{t.onclick=()=>selectPhase(i);t.onkeydown=e=>{let j=i;if(e.key==='ArrowLeft')j=(i+1)%5;else if(e.key==='ArrowRight')j=(i+4)%5;else if(e.key==='Home')j=0;else if(e.key==='End')j=4;else return;e.preventDefault();selectPhase(j,true)}});selectPhase(0);
const photos=[['جنگل ابر، نمای آغاز','Abr Jungle in Iran by Pouria Afkhami pixoos 05.jpg','Pouria Afkhami / Pixoos','4.0','by-sa'],['جنگل ابر، دنیای سبز','Abr Jungle in Iran by Pouria Afkhami pixoos 02.jpg','Pouria Afkhami / Pixoos','4.0','by-sa'],['مجموعه تاریخی بسطام','Bayazid Bastami 21.jpg','Reza Sobhani / Arosha-photo','4.0','by-sa'],['خانه یغمایی شاهرود','خانۀ یغمایی شاهرود 1.jpg','Sasan77Abdi','4.0','by-sa'],['چشم‌انداز مجن و شاهوار','Mojen - Shahvar - panoramio.jpg','Alireza Javaheri','3.0','by']];
$('#photo-credits').innerHTML=photos.map(p=>`<li><a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(p[1].replaceAll(' ','_'))}" target="_blank" rel="noopener">${p[0]}</a> — ${p[2]} · <a href="https://creativecommons.org/licenses/${p[4]}/${p[3]}/" target="_blank" rel="noopener">CC ${p[4].toUpperCase()} ${p[3]}</a></li>`).join('');
let activePhoto=0;
function activate(i){if(i===current)return;current=i;const w=worlds[i];document.documentElement.style.setProperty('--accent',w.color);chapters.forEach((c,j)=>c.classList.toggle('is-active',i===j));$$('.rail-item').forEach((r,j)=>{r.classList.toggle('active',i===j);if(i===j)r.setAttribute('aria-current','step');else r.removeAttribute('aria-current')});$('#place-name').textContent=w.place;$('#chapter-no').textContent=w.num;$('#scene-label').textContent=w.en;const layers=$$('.photo-layer');const next=1-activePhoto;layers[next].style.backgroundImage=`url('assets/${w.photo}')`;layers[next].classList.add('active');layers[activePhoto].classList.remove('active');activePhoto=next;scene?.setWorld(i);}
let scheduled=false;
function updateScroll(){scheduled=false;const y=scrollY,h=innerHeight;let closest=0;chapters.forEach((c,i)=>{if(c.getBoundingClientRect().top<=h*.38)closest=i});activate(closest);const rect=chapters[current].getBoundingClientRect();progress=Math.max(0,Math.min(1,(-rect.top+h*.12)/rect.height));scene?.setProgress(progress);let spatial=0;const travelY=y+h*.12;for(let i=0;i<chapters.length;i++){const top=chapters[i].getBoundingClientRect().top+y;const end=i<chapters.length-1?chapters[i+1].getBoundingClientRect().top+y:$('#roadmap').getBoundingClientRect().top+y;if(travelY>=top)spatial=i+Math.max(0,Math.min(.999,(travelY-top)/(end-top)));}const stop=Math.floor(spatial),fraction=spatial-stop,travel=Math.max(0,Math.min(1,(fraction-.18)/.68));scene?.setJourney(stop+travel*travel*(3-2*travel));const local=spatial%1;const smooth=(a,b,v)=>{const t=Math.max(0,Math.min(1,(v-a)/(b-a)));return t*t*(3-2*t)};const reading=reduced?1:1-smooth(.25,.4,local)*(1-smooth(.72,.9,local))*.94;document.documentElement.style.setProperty('--reading-opacity',String(reading));document.body.classList.toggle('journey-travel',reading<.2);$('.scroll-progress div').style.width=(y/(document.documentElement.scrollHeight-h)*100)+'%';document.body.classList.toggle('scrolled',y>60);const beyond=$('#roadmap').getBoundingClientRect().top<h*.7;document.body.classList.toggle('in-roadmap',beyond);$('.chapter-rail').style.opacity=beyond?'0':'1';$('.chapter-rail').style.pointerEvents=beyond?'none':'auto';$('.ambient-label').style.opacity=beyond?'0':'1';$('#world').style.opacity=beyond?'0':'1';if(!reduced){const offset=(progress-.5)*18;$$('.photo-layer').forEach(p=>p.style.transform=`scale(1.035) translateY(${offset}px)`);}}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll)}},{passive:true});addEventListener('resize',updateScroll);
$('#motion-toggle').onclick=()=>{reduced=!reduced;document.body.classList.toggle('reduced-motion',reduced);$('#motion-toggle').setAttribute('aria-pressed',String(reduced));scene?.setReduced(reduced);updateScroll();};
worlds.forEach(w=>{const img=new Image();img.src='assets/'+w.photo;});
import('./network.js').then(m=>m.renderNetwork(showFeature));
import('./lateral.js').then(({createScene})=>{scene=createScene($('#world'),showFeature);scene.setReduced(reduced);scene.setWorld(current);window.__sceneReady=true;updateScroll();}).catch(e=>{document.body.classList.add('webgl-fallback');console.warn('3D scene unavailable; photo journey remains available.',e)});
updateScroll();window.__journey={worlds:worlds.length,features:allFeatures.length,showFeature,goTo,get current(){return current},get reduced(){return reduced}};

document.body.classList.add('lateral-gallery');
document.querySelector('header nav a').href='#stop-assistant';
document.querySelector('header nav a').textContent='امکانات شهر';
document.querySelector('.hud-number').innerHTML='<b id="chapter-no">۰۰</b><i>/</i>۲۰';
document.querySelector('.atlas-dialog h2').textContent='کدام امکان را می‌خواهید ببینید؟';
document.body.insertAdjacentHTML('beforeend','<nav class="lateral-controls" aria-label="حرکت افقی بین امکانات"><button id="station-next" aria-label="امکان بعدی، حرکت به چپ"><span>←</span><small>امکان بعدی</small></button><div><b id="station-current">۰۰</b><span> / ۲۰</span></div><button id="station-prev" aria-label="امکان قبلی، حرکت به راست"><span>→</span><small>امکان قبلی</small></button></nav>');
function lateralStatus(){document.querySelector('#station-current').textContent=stations[current].num;document.querySelector('#station-prev').disabled=current===0;document.querySelector('#station-next').disabled=current===stations.length-1;}
document.querySelector('#station-next').onclick=()=>goTo(Math.min(stations.length-1,current+1));
document.querySelector('#station-prev').onclick=()=>goTo(Math.max(0,current-1));
addEventListener('scroll',lateralStatus,{passive:true});lateralStatus();
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.target.closest('input,select,button,[role="tab"]')||document.body.classList.contains('in-roadmap'))return;if(e.key==='ArrowLeft'){e.preventDefault();goTo(Math.min(stations.length-1,current+1))}if(e.key==='ArrowRight'){e.preventDefault();goTo(Math.max(0,current-1))}});
let swipe=null;addEventListener('touchstart',e=>{if(!e.target.closest('dialog'))swipe=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});addEventListener('touchend',e=>{if(!swipe)return;const dx=e.changedTouches[0].clientX-swipe[0],dy=e.changedTouches[0].clientY-swipe[1];swipe=null;if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.5)goTo(Math.max(0,Math.min(stations.length-1,current+(dx<0?1:-1))))},{passive:true});
fetch('assets/station-photo-sources.json').then(r=>r.json()).then(items=>{document.querySelector('#photo-credits').insertAdjacentHTML('beforeend',items.map(p=>'<li><a target="_blank" rel="noopener" href="'+p.url+'">تصویر موضوعی '+p.file+'</a> — '+p.author+' · <a href="https://unsplash.com/license" target="_blank" rel="noopener">Unsplash License</a></li>').join(''))}).catch(()=>{});
